svg.script:
(function () {
  var root = document.getElementById('isoFlow');
  var step = 0;
  var busy = false;
  var DURATION = { 0: 750, 1: 1750, 2: 1400, 3: 1100 };

  function play(next) {
    busy = true;
    step = next;
    root.setAttribute('data-step', String(next));
    root.setAttribute('data-anim', '1');
    window.setTimeout(function () {
      root.removeAttribute('data-anim');
      busy = false;
    }, DURATION[next]);
  }

  root.addEventListener('click', function () {
    if (busy) {
      return;
    }
    play((step + 1) % 4);
  });
})();
